import { createSignal, createMemo } from 'solid-js';

// ❌ OLD: Side effects inside createMemo. Memos are lazy and pure:
// they may run zero times (if never read) or run once per change
// (if read by many consumers). Tracking here fires unpredictably.
const [count, setCount] = createSignal(0);

const doubled = createMemo(() => {
  analytics.track('doubled-view'); // ❌ OLD: runs only when read + dirty
  return count() * 2;
});

// If nothing reads doubled() after a change, the track never fires;
// if ten nodes read it, it still fires once (cached). The analytics
// call has NO predictable relationship to user actions.

