import { createSignal, createEffect } from 'solid-js';

// ✅ NEW: Effects are the designated place for side effects. The
// callback runs once initially, then again whenever count() changes
// (batched to one run per flush). Cleanup runs before each re-run.
const [count, setCount] = createSignal(0);

createEffect(() => {
  analytics.track('count', count()); // ✅ NEW: deterministic per change
});

// If the effect needs teardown, return a cleanup function:
createEffect(() => {
  const sub = subscribe(count());
  return () => sub.unsubscribe(); // ✅ NEW: runs before the next effect run
});
